<script lang="ts">
	/**
	 * The page ground for everything outside a match.
	 *
	 * Deliberately not a grid: the sponsor's site (DontCode) already uses a
	 * ruled grid backdrop, and reusing one here made the two read as the same
	 * property. Contours say more anyway, since terrain height is what actually
	 * decides sight lines and combat in this game, so the ground under the
	 * interface is a survey of the thing being played.
	 *
	 * Every fifth line on a real topographic map is drawn heavier as an index
	 * contour, which is the only reason the paths come in two sets.
	 */
	interface Props {
		/** Reversed panels (the olive auth column) draw in their own foreground. */
		tone?: 'ink' | 'reverse'
		class?: string
	}

	let { tone = 'ink', class: className = '' }: Props = $props()
</script>

