<style>
	.ground {
		position: absolute;
		inset: 0;
		overflow: hidden;
		pointer-events: none;
		color: hsl(var(--ink));
	}
	.ground[data-tone='reverse'] {
		color: var(--primary-foreground);
	}
	.contours {
		position: absolute;
		inset: 0;
		width: 100%;
		height: 100%;
	}
	.minor {
		opacity: 0.07;
	}
	.index {
		opacity: 0.11;
	}
	.ground[data-tone='reverse'] .minor {
		opacity: 0.1;
	}
	.ground[data-tone='reverse'] .index {
		opacity: 0.16;
	}
	/* Paper tooth, so the flat areas between contours still have a surface. */
	.grain {
		position: absolute;
		inset: 0;
		background-image: url("data:image/svg+xml;utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='140' height='140'%3E%3Cfilter id='g'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.82' numOctaves='3' stitchTiles='stitch'/%3E%3CfeColorMatrix type='saturate' values='0'/%3E%3C/filter%3E%3Crect width='140' height='140' filter='url(%23g)' opacity='0.5'/%3E%3C/svg%3E");
		opacity: var(--grain-opacity);
		mix-blend-mode: multiply;
	}
	:global(.dark) .grain,
	.ground[data-tone='reverse'] .grain {
		mix-blend-mode: overlay;
	}
</style>
